mapper.select:
select from product_spu s where s.status = 'ON_SALE'
and s.category_key = #{category}
and (s.default_name like concat('%', #{q}, '%') or s.name_en like concat('%', #{q}, '%') or s.brand_name like concat('%', #{q}, '%'))
order by
priceUsd asc, s.spu_id desc priceUsd desc, s.spu_id desc s.rating desc, s.spu_id desc s.sold_count desc, s.spu_id desc s.sold_count desc, s.spu_id desc
limit #{offset}, #{size}

select count(*) from product_spu s where s.status = 'ON_SALE'
and s.category_key = #{category}
and (s.default_name like concat('%', #{q}, '%') or s.name_en like concat('%', #{q}, '%') or s.brand_name like concat('%', #{q}, '%'))

select 
from product_spu s
where s.spu_id = #{spuId}

select k.spu_id as spuId, k.sku_id as skuId, k.sku_code as skuCode, k.attributes_json as attributesJson, k.weight_grams as weightG, k.hs_code as hsCode, k.declared_name as declaredName, k.declared_value_amount as declaredAmount, k.status as status, ifnull((select sum(i.total_qty - i.locked_qty) from inventory i where i.sku_id = k.sku_id), 0) as stock, (select sp.sale_amount from sku_price sp where sp.sku_id = k.sku_id and sp.currency_code = 'USD' and sp.status = 'ACTIVE' order by sp.effective_from desc limit 1) as priceUsd, (select sp.sale_amount from sku_price sp where sp.sku_id = k.sku_id and sp.currency_code = 'EUR' and sp.status = 'ACTIVE' order by sp.effective_from desc limit 1) as priceEur, (select sp.sale_amount from sku_price sp where sp.sku_id = k.sku_id and sp.currency_code = 'CNY' and sp.status = 'ACTIVE' order by sp.effective_from desc limit 1) as priceCny from product_sku k where k.spu_id in
#{spuId}
order by k.spu_id, k.sku_id

select k.spu_id as spuId, i.warehouse_code as warehouseCode, ifnull(sum(i.total_qty - i.locked_qty), 0) as available from inventory i inner join product_sku k on k.sku_id = i.sku_id where k.spu_id in
#{spuId}
group by k.spu_id, i.warehouse_code order by k.spu_id, i.warehouse_code

select distinct k.spu_id as spuId, cl.channel_code as channelCode, cl.listing_status as listingStatus from channel_listing cl inner join product_sku k on k.sku_id = cl.sku_id where k.spu_id in
#{spuId}
order by k.spu_id, cl.channel_code

select o.order_id as orderId, o.order_no as orderNo, o.shop_id as shopId, o.customer_id as customerId, o.channel_code as channelCode, o.country_code as countryCode, o.currency_code as currencyCode, o.subtotal_amount as subtotalAmount, o.discount_amount as discountAmount, o.shipping_amount as shippingAmount, o.tax_amount as taxAmount, o.total_amount as totalAmount, o.order_status as status, o.payment_status as paymentStatus, o.fulfillment_status as fulfillmentStatus, o.after_sale_status as afterSaleStatus, o.placed_at as placedAt, o.create_time as createTime from orders o where o.customer_id = #{customerId}
and o.order_status = #{status}
order by ifnull(o.placed_at, o.create_time) desc, o.order_id desc

select oi.order_id as orderId, oi.order_item_id as orderItemId, oi.sku_id as skuId, oi.sku_code as skuCode, oi.quantity as quantity, oi.unit_price_amount as unitPriceAmount, oi.line_total_amount as lineTotalAmount, oi.currency_code as currencyCode, sn.product_name as name, sn.image_url as image, sn.attributes_json as attributesJson from order_items oi left join order_item_snapshots sn on sn.order_item_id = oi.order_item_id where oi.order_id in
#{orderId}
order by oi.order_id, oi.order_item_id
